2	import { formatMoney } from '../../ui/money';
3	import { InvoiceLineItems } from './InvoiceLineItems';
4	import { ProjectTags } from './ProjectTags';
5	import { ProjectNotes } from './ProjectNotes';
6	
7	// Opened from the projects list: a project's detail view lists ITS invoices, shows the derived
8	// total, and lets you add a new invoice for an amount. Invoices are scoped to the project via
9	// /api/projects/<id>/invoices. Money renders with exactly two decimals.
10	type Invoice = {
11	  id: number;
12	  projectId: number;
13	  amount: number;
14	  status: string;
15	  issuedDate: string;
16	  dueDate: string;
17	  // How much is still left to pay: the invoice amount minus any payments recorded against it.
18	  dueAmount: number;
19	};
20	
21	type Task = {
22	  id: number;
23	  projectId: number;
24	  title: string;
25	  done: boolean;
26	};
27	
28	// A project's budget position: the budget set on it, how much has been invoiced against it, and what
29	// is left (budget minus invoiced).
30	type Budget = {
31	  budget: number;
32	  invoiced: number;
33	  remaining: number;
34	};
35	
36	export function ProjectDetail({ projectId }: { projectId: number }) {
37	  const [invoices, setInvoices] = useState<Invoice[]>([]);
38	  const [budget, setBudget] = useState<Budget | null>(null);
39	  const [tasks, setTasks] = useState<Task[]>([]);
40	  // Which tasks to show: all of them, just the open ones, or just the finished ones.
41	  const [taskFilter, setTaskFilter] = useState('');
42	  const [amount, setAmount] = useState('');
43	  const [amountError, setAmountError] = useState(false);
44	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
45	
46	  async function load() {
47	    const res = await fetch(`/api/projects/${projectId}/invoices`);
48	    if (res.ok) {
49	      setInvoices(await res.json());
50	    }
51	    const budgetRes = await fetch(`/api/projects/${projectId}/budget`);
52	    if (budgetRes.ok) {
53	      setBudget(await budgetRes.json());
54	    }
55	  }
56	
57	  async function loadTasks() {
58	    const query = taskFilter ? `?filter=${encodeURIComponent(taskFilter)}` : '';
59	    const res = await fetch(`/api/projects/${projectId}/tasks${query}`);
60	    if (res.ok) {
61	      setTasks(await res.json());
62	    }
63	  }
64	
65	  useEffect(() => {
66	    void load();
67	  }, [projectId]);
68	
69	  useEffect(() => {
70	    void loadTasks();
71	  }, [projectId, taskFilter]);
72	
73	  // Tick a task off (or back on): toggles OPEN <-> DONE and reloads the list.
74	  async function onToggleTask(taskId: number) {
75	    const res = await fetch(`/api/tasks/${taskId}/toggle`, { method: 'POST' });
76	    if (res.ok) {
77	      await loadTasks();
78	    }
79	  }
80	
81	  async function onSubmit(event: FormEvent) {
82	    event.preventDefault();
83	    // An invoice must be for a real amount: a positive number, never zero or negative.
84	    const value = Number(amount);
85	    if (!(value > 0)) {
86	      setAmountError(true);
87	      return;
88	    }
89	    setAmountError(false);
90	    const res = await fetch(`/api/projects/${projectId}/invoices`, {
91	      method: 'POST',
92	      headers: { 'Content-Type': 'application/json' },
93	      body: JSON.stringify({ amount: Number(amount) }),
94	    });
95	    if (res.ok) {
96	      setAmount('');
97	      await load();
98	    }
